        border_width: 0.0,
        z: 0.0,
        shadow_blur: 0.0,
        shadow_spread: 0.0,
        shadow_color: [0.0; 4],
        shadow_offset: [0.0; 2],
        _pad: [0.0; 2],
    });

    if value > 0.0 {
        let fill_rect = [rect[0], rect[1], rect[2] * value, rect[3]];
        core.draw_list.push_quad(QuadCall {
