#[derive(Clone, Copy, Debug, PartialEq)]
pub enum BadgeVariant {
    Default,
    Primary,
    Success,
    Warning,
    Error,
    Info,
}

pub struct BadgeStyle {
    pub fill: Option<u32>,
    pub border_color: Option<u32>,
    pub content_color: Option<u32>,
    pub text_style: Option<TextStyle>,
}

impl BadgeStyle {
    pub fn empty() -> Self {
        Self {
            fill: None,
            border_color: None,
            content_color: None,
            text_style: None,
        }
    }
}

pub fn badge(
    core: &mut AkarCore,
    layout: &Layout,
    node_id: NodeId,
    text: &str,
    variant: BadgeVariant,
    theme: &AkarTheme,
) {
    let style = BadgeStyle::empty();
    badge_styled(core, layout, node_id, text, variant, &style, theme)
}

pub fn badge_styled(
    core: &mut AkarCore,
    layout: &Layout,
    node_id: NodeId,
    text: &str,
    variant: BadgeVariant,
    style: &BadgeStyle,
    theme: &AkarTheme,
) {
