use akar_core::{AkarCore, QuadCall};
use akar_layout::{Layout, NodeId};

use crate::color::color_to_f32;
use crate::AkarTheme;

pub struct SeparatorStyle {
    pub color: Option<u32>,
    pub thickness: Option<f32>,
}

impl SeparatorStyle {
    pub fn empty() -> Self {
        Self {
            color: None,
            thickness: None,
        }
    }
}

pub fn separator(core: &mut AkarCore, layout: &Layout, node_id: NodeId, theme: &AkarTheme) {
    let style = SeparatorStyle::empty();
    separator_styled(core, layout, node_id, &style, theme)
}

pub fn separator_styled(
    core: &mut AkarCore,
    layout: &Layout,
    node_id: NodeId,
    style: &SeparatorStyle,
    theme: &AkarTheme,
) {
    let rect = layout.rect(node_id);
    if rect[2] == 0.0 || rect[3] == 0.0 {
        return;
    }

    let thickness = style.thickness.unwrap_or(1.0);
    let color = style.color.unwrap_or(theme.base_300);

    let styled_rect = [
        rect[0],
        rect[1] + (rect[3] - thickness) * 0.5,
        rect[2],
        thickness,
    ];

    core.draw_list.push_quad(QuadCall {
        rect: styled_rect,
        fill: color_to_f32(color),
        border_color: [0.0; 4],
        corner_radii: [0.0; 4],
        border_width: 0.0,
        z: 0.0,
        shadow_blur: 0.0,
        shadow_spread: 0.0,
        shadow_color: [0.0; 4],
        shadow_offset: [0.0; 2],
        _pad: [0.0; 2],
    });
}

