pub fn tab_bar(
    core: &mut AkarCore,
    layout: &Layout,
    node_id: NodeId,
    labels: &[&str],
    active_index: usize,
    variant: TabVariant,
    theme: &AkarTheme,
) -> TabBarResponse {
    let style = TabBarStyle::empty();
    tab_bar_styled(core, layout, node_id, labels, active_index, variant, &style, theme)
}

pub fn tab_bar_styled(
    core: &mut AkarCore,
    layout: &Layout,
    node_id: NodeId,
    labels: &[&str],
    active_index: usize,
    variant: TabVariant,
    style: &TabBarStyle,
    theme: &AkarTheme,
) -> TabBarResponse {
    let rect = layout.rect(node_id);

    if rect[2] == 0.0 || rect[3] == 0.0 {
        return TabBarResponse { clicked: None };
    }

    if labels.is_empty() {
        return TabBarResponse { clicked: None };
    }

    let count = labels.len();
    let tab_width = rect[2] / count as f32;

    let active_color = style.active_color.unwrap_or(theme.primary);
    let inactive_color = style.inactive_color.unwrap_or(theme.base_200);
    let indicator_color = style.indicator_color.unwrap_or(theme.primary);

    let mut clicked = None;
    for i in 0..count {
        let tab_rect = [rect[0] + i as f32 * tab_width, rect[1], tab_width, rect[3]];
        if core.input.is_clicked(tab_rect) {
            clicked = Some(i);
        }
    }

    let active = clicked.unwrap_or(active_index).min(count - 1);

    for (i, label) in labels.iter().enumerate() {
        let tab_rect = [rect[0] + i as f32 * tab_width, rect[1], tab_width, rect[3]];

        let is_active = i == active;

        match variant {
            TabVariant::Boxed => {
                let (fill, border) = if is_active {
                    (active_color, active_color)
                } else {
                    (inactive_color, style.inactive_color.map(|_| inactive_color).unwrap_or(theme.base_300))
                };
                core.draw_list.push_quad(QuadCall {
                    rect: tab_rect,
                    fill: color_to_f32(fill),
                    border_color: color_to_f32(border),
                    corner_radii: [theme.radius_field; 4],
                    border_width: theme.border_width,
                    z: 0.0,
                    shadow_blur: 0.0,
                    shadow_spread: 0.0,
                    shadow_color: [0.0; 4],
                    shadow_offset: [0.0; 2],
                    _pad: [0.0; 2],
                });
            }
            TabVariant::Lifted => {
                let fill = if is_active {
                    theme.base_100
                } else {
                    inactive_color
                };
                core.draw_list.push_quad(QuadCall {
                    rect: tab_rect,
                    fill: color_to_f32(fill),
                    border_color: [0.0; 4],
                    corner_radii: [theme.radius_field, theme.radius_field, 0.0, 0.0],
