            {
                expected |= Self::SUPER.0;
            }
            #[cfg(not(target_os = "macos"))]
            {
                expected |= Self::CONTROL.0;
            }
        }

        let actual = (if modifiers.control {
            Self::CONTROL.0
        } else {
            0
        }) | (if modifiers.super_key {
            Self::SUPER.0
        } else {
            0
        }) | (if modifiers.alt { Self::ALT.0 } else { 0 })
            | (if modifiers.shift { Self::SHIFT.0 } else { 0 });
        actual == expected
    }
}

